import { mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { defaultAutonomy } from '@ripple/shared';
import type { Journal } from '../journal.ts';
import type { ProjectStore } from '../projects.ts';
import type { ContentStore } from '../content/store.ts';
import { formatStats } from '../content/team.ts';
import { readFileSync } from 'node:fs';
import { addDays, day, type AccountPost, type Item, type ItemKind, type Media } from '../content/types.ts';

// What the team really produced on 2 Nov 2026 for Mairie360 (Scout: field audit and competitor watch; Analyst; Strategist's
// proposals; Director's plan and note), saved once from a real pass so the demo shows true work without paying for it again.
const REAL = JSON.parse(readFileSync(join(import.meta.dirname, 'real.json'), 'utf8')) as {
  readAt: string; watch: unknown; audit: unknown; account: { summary: string; strengths: string[]; gaps: string[]; opportunities: string[]; winners?: unknown[]; losers?: unknown[] }; plan: unknown; synthesis: unknown;
  ideas: Array<{ kind: ItemKind; title: string; brief: string; rationale: string; proof?: Item['proof']; pitch?: Item['pitch']; source: Item['source']; offsetDays?: number; fixedDate?: string; milestoneId?: string }>;
  activity: Array<{ agent: 'scout' | 'analyst' | 'strategist' | 'writer' | 'director'; summary: string; ok: boolean }>;
};

// Real pictures for the demo posts, generated once with the image model and embedded,
// so the demo shows true images without calling the model on every seed.
const PICTURES: Record<string, string> = {
  hall: '',
  desk: '',
  square: '',
};

export const DEMO_PROJECT = 'mairie360-demo';

// The demo studio works on Mairie360: a platform for French town halls (projects, calendar,
// messaging, workflows, training) built by four Epitech students, with partner communes.
// The dates of the goal and the four pieces in progress are hand-written; the research is the real pass (real.json).
// The account posts are the real ones of Mairie360, read on 2 Nov 2026 and kept in account.json next to this
// file (Instagram: public page, text, date and likes; LinkedIn: page admin, reactions, reposts, impressions).
// Nothing is scraped at run time: a real project either pastes its export on the Platforms page, or connects
// the Instagram API in .env and lets the Scout read it at each pass.
const ACCOUNT = JSON.parse(readFileSync(join(import.meta.dirname, 'account.json'), 'utf8')) as {
  instagram: { readAt: string; followers: number; posts: Array<[string, string, string, number]> };
  linkedin: { readAt: string; followers: number; posts: Array<[string, string, string, number, number, number]> };
};
const realPosts = (): AccountPost[] => ACCOUNT.instagram.posts.map(([postedAt, format, text, likes]) => ({ platform: 'instagram', text, format, likes, comments: 0, shares: 0, saves: 0, postedAt, simulated: false }));
const realLinkedIn = (): AccountPost[] => ACCOUNT.linkedin.posts.map(([postedAt, format, text, likes, shares, views]) => ({ platform: 'linkedin', text, format, likes, comments: 0, shares, saves: 0, views, postedAt, simulated: false }));

// A project in the middle of its life, to try the studio without spending a single model call.
export function seedDemo(o: { journal: Journal; projects: ProjectStore; content: ContentStore; mediaDir: string; repoPath: string; now?: Date }) {
  const now = o.now ?? new Date();
  const today = day(now);
  const d = (n: number) => addDays(today, n);
  const at = (n: number) => new Date(now.getTime() + n * 86_400_000).toISOString();
  const P = DEMO_PROJECT;
  const { journal, content: s } = o;

  o.projects.add({ id: P, name: 'Mairie360 (demo)', path: o.repoPath, repoUrl: 'https://github.com/mairie360', source: 'link' });

  // --- features, replayed into the journal the way the runtime would have written them
  const feature = (id: string, title: string, summary: string, steps: Array<Record<string, unknown>>) => {
    journal.append(id, 'CREATED', { title, design: summary, projectId: P, autonomy: defaultAutonomy });
    journal.append(id, 'PLAN', { summary, needsInput: false, reason: '', steps: [{ title, detail: summary }], options: [] });
    journal.append(id, 'BUILD', { branch: `mair-${id}`, stat: '9 files changed, 341 insertions(+), 27 deletions(-)', diff: '' });
    for (const e of steps) journal.append(id, 'EVENT', e);
    if (steps.some(e => e.type === 'MERGE_DONE')) journal.append(id, 'MERGE', { commit: 'c4d19e2', pushed: false });
  };
  const toPlan = [{ type: 'PLAN_READY' }, { type: 'APPROVE', gate: 'plan' }, { type: 'BUILD_DONE' }, { type: 'VISUAL_OK' }];
  const toMerged = [...toPlan, { type: 'APPROVE', gate: 'merge' }, { type: 'MERGE_DONE' }];
  feature('notification-drawer', 'Notification drawer', 'One drawer shared by every module: a task assigned, a meeting moved, a message received', toMerged);
  feature('attachment-download', 'Attachments in Messages', 'Download the files attached to a conversation, with unavailable files refused up front', toPlan); // built and checked, waiting for the merge

  // --- the team's profile and standing orders
  s.setProfile(P, {
    autopilot: true, // the team keeps watching on its own, about once a day, while the demo runs
    voice: 'Plain and warm, like a colleague from the next office. Concrete scenes from a town hall, short sentences, no vendor talk. Vouvoiement.',
    audience: 'Secrétaires de mairie, directeurs généraux des services and elected officials of small French communes, mostly on LinkedIn',
    language: 'French',
    autoDraft: false,
    niche: 'a shared workspace for French town halls: projects, calendar, messaging, workflows and training',
    directives: 'Never publish a price. Never name a partner commune without its written consent. At most two posts a week, LinkedIn first. Say "mairie", not "client".',
    publishMode: 'local',
  });

  // --- roadmap: one goal, two projections (the second corrects the first: the pace is slower than the plan)
  const pilot = s.addMilestone({ projectId: P, title: 'Beta with municipal teams', intent: 'The beta testers recruited on Instagram get their access and send their first feedback. The story: built with the agents, not for them.', targetDate: d(18), startDate: d(-12), scope: 4, createdAt: at(-12) });
  for (const f of ['notification-drawer', 'attachment-download']) s.link(pilot.id, f);
  s.addForecast({ milestoneId: pilot.id, madeAt: at(-12), predictedDate: d(18), rawRemainingDays: 30, calibration: 1, done: 0, scope: 4, confidence: 'low', note: 'First projection, taken from your own plan.' });
  s.addForecast({ milestoneId: pilot.id, madeAt: at(-5), predictedDate: d(24), rawRemainingDays: 21, calibration: 1.3, done: 1, scope: 4, confidence: 'medium', note: 'One of four delivered after 7 days. The pace is slower than the plan, so I correct for it: x1.3.' });

  // --- what the Scout found, and the Analyst's comparison with the account
  s.addReport(P, 'audit', REAL.audit, false, at(-0.03)); // the Scout's real field audit (web search), kept as produced
  const posts = realPosts();
  const linkedin = realLinkedIn();
  const all = [...posts, ...linkedin];
  s.setAccount(P, all);
  s.snapshot(P, { at: at(0), platform: 'instagram', followers: ACCOUNT.instagram.followers, posts: posts.length }); // read on the public page the same day
  s.snapshot(P, { at: at(0), platform: 'linkedin', followers: ACCOUNT.linkedin.followers, posts: linkedin.length }); // read in the page admin the same day
  s.addReport(P, 'account', { ...REAL.account, stats: formatStats(all), postCount: all.length }, false, at(-0.02)); // the Analyst's real reading of the 32 posts

  // --- content, at every stage
  const add = (i: { kind: ItemKind; title: string; brief: string } & Partial<Omit<Item, 'id' | 'projectId' | 'createdAt' | 'revisions'>>) =>
    s.addItem({ projectId: P, origin: 'user', createdAt: at(-2), ...i });
  const pic = (name: string, itemId: string, file: string) => { mkdirSync(join(o.mediaDir, itemId), { recursive: true }); writeFileSync(join(o.mediaDir, itemId, file), Buffer.from(PICTURES[name], 'base64')); return file; };
  const media = (format: Media['format'], hashtags: string[], slides: Media['slides']): Media => ({ format, hashtags, slides });

  // the Strategist's real proposals, hung on the beta or dated
  const stats = formatStats(all);
  for (const i of REAL.ideas) {
    const { milestoneId, fixedDate, offsetDays, ...rest } = i;
    add({ ...rest, origin: 'ai', status: 'idea', ...(milestoneId && offsetDays !== undefined ? { milestoneId: pilot.id, offsetDays } : { fixedDate: fixedDate && fixedDate >= today ? fixedDate : d(5) }) });
  }

  // a carousel, drafted, two pictures generated
  const carousel = add({ kind: 'social-post', title: 'Bêta : ce que vous verrez en premier', brief: 'For the people who signed up: what the first login shows, who to write to, no price.', status: 'drafted', milestoneId: pilot.id, offsetDays: -14, pitch: { hook: 'Dans trois semaines, les premiers bêta testeurs ouvrent Mairie360.', channel: 'Instagram and LinkedIn', measure: 'Replies and sign-ups from the carousel link, compared with the 11 October call' }, rationale: 'The 11 October call for testers got 8 likes and no comment: people liked, nobody wrote. Showing what the first screen looks like gives them something to react to.', source: 'account' });
  s.updateItem(carousel.id, {
    draft: 'Dans trois semaines, les premiers bêta testeurs ouvrent Mairie360.\n\nPremière chose à l’écran : la journée. Les projets en cours, les tâches à faire, les rendez-vous, au même endroit, dès la connexion.\n\nPas de formation à suivre avant de commencer. Une personne de l’équipe répond à chaque message.\n\nIl reste des places : le lien est dans la bio.',
    revisions: 2,
    media: media('carousel', ['#mairie', '#collectivités', '#secrétairedemairie', '#communesrurales', '#civictech'], [
      { kind: 'image', visual: 'Meeting room of a small town hall in the morning, a laptop open on a wooden table next to a paper agenda and a stamp, tricolour flag in the corner', text: 'La bêta, dans trois semaines', seconds: 0, file: pic('hall', carousel.id, '1-demo.jpg') },
      { kind: 'image', visual: 'Hands of a clerk at the front desk holding a phone that shows a colourful week calendar, folders and a landline behind', text: 'La journée dès la connexion', seconds: 0, file: pic('desk', carousel.id, '2-demo.jpg') },
      { kind: 'image', visual: 'A village square at the end of the afternoon, the stone facade of the mairie with its flag, a few people crossing', text: 'Le lien est dans la bio', seconds: 0 },
    ]),
  });

  // an approved single image and a published devlog
  const single = add({ kind: 'social-post', title: 'Le tiroir de notifications est arrivé', brief: 'Short, one scene, no feature list.', status: 'approved', fixedDate: d(1), pitch: { hook: 'Une tâche assignée, une réunion déplacée, un message reçu : tout arrive au même endroit.', channel: 'Instagram', measure: 'Whether anyone asks how to get it: that is the question to answer in comments' }, rationale: 'The notification drawer is merged, the first finished feature since the beta call. One scene, no feature list.', source: 'roadmap' });
  s.updateItem(single.id, { draft: 'Une tâche assignée, une réunion déplacée, un message reçu : tout arrive au même endroit, quel que soit le module ouvert.\n\nPlus de tour des onglets le matin.\n\nLe tiroir de notifications, maintenant dans Mairie360.', revisions: 1, media: media('image', ['#mairie', '#collectivités', '#civictech'], [{ kind: 'image', visual: 'A village square at the end of the afternoon, the stone facade of the mairie with its flag, soft golden light', text: 'Tout arrive au même endroit', seconds: 0, file: pic('square', single.id, '1-demo.jpg') }]) });
  add({ kind: 'devlog', title: 'Semaine 6 : ce que l’accueil nous a appris', brief: 'x', status: 'published', fixedDate: d(-6), draft: 'Une matinée derrière le comptoir de notre commune partenaire. Sept logiciels ouverts, un agenda papier, un fax qui marche encore. Voici ce que nous avons retiré de l’écran Projets en rentrant.' });
  add({ kind: 'newsletter', title: 'Lettre aux bêta testeurs : le programme, concrètement', brief: 'Tell the people who signed up what the beta contains, when it starts, and how feedback is collected.', status: 'briefed', milestoneId: pilot.id, offsetDays: -7, pitch: { hook: 'Vous vous êtes inscrit à la bêta de Mairie360. Voici ce qui se passe maintenant.', channel: 'Email to the sign-ups', measure: 'Replies to the email, and how many open their access the first week' }, rationale: 'The people who signed up through the form have heard nothing since. One email before the beta keeps them.', source: 'roadmap' });

  // --- what the team did, as it said it: the log lines of the real pass, then its plan and its note
  REAL.activity.forEach((l, n) => s.log(P, l.agent, l.summary, l.ok, at(-0.03 + n * 0.004)));
  s.addReport(P, 'watch', REAL.watch, false, at(-0.028));
  s.addReport(P, 'plan', REAL.plan, false, at(-0.008));
  s.addReport(P, 'synthesis', REAL.synthesis, false, at(-0.006));
  s.setAgentConfig(P, 'scout', { workers: 2 });
  s.setAgentConfig(P, 'writer', { instructions: 'French, vouvoiement, under 600 characters. One scene from a town hall per post, never a feature list, never a price.' });
  s.addChat(P, 'director', 'user', 'What should we post this week?', [], at(-0.004));
  s.addChat(P, 'director', 'agent', 'Record the first-login reel first: your two reels are in your top tier and the field saves that format most. I can also have the Strategist look at the beta for teasers.', [
    { kind: 'run', label: 'Plan the beta teasers', agents: ['strategist'], brief: 'Teasers for the beta with municipal teams' },
    { kind: 'talk', label: 'Talk to the Strategist', agent: 'strategist' },
  ], at(-0.003));
}
